(()=>{const t=document.getElementById("practice-container");[{title:"練習一：技術分析基礎",link:"/practice1",description:"測試您對技術分析基本概念的理解。"},{title:"練習二：基本面分析",link:"/practice2",description:"練習如何分析公司的基本面資料。"},{title:"練習三：K線圖與型態辨識",link:"/practice3",description:"挑戰您的K線圖和價格型態辨識能力。"},{title:"練習四：簡單移動平均線（SMA）",link:"/practice4",description:"練習計算和應用簡單移動平均線。"},{title:"練習五：相對強弱指數（RSI）",link:"/practice5",description:"測試您使用RSI判斷市場狀態的能力。"},{title:"練習六：布林帶（Bollinger Bands）",link:"/practice6",description:"練習布林帶的計算及其應用。"},{title:"練習七：MACD指標",link:"/practice7",description:"挑戰您對MACD指標的使用技巧。"},{title:"練習八：KD指標（Stochastic Oscillator）",link:"/practice8",description:"練習使用KD指標判斷市場趨勢。"},{title:"練習九：乖離率（BIAS）",link:"/practice9",description:"測試您對乖離率的理解及應用能力。"}].forEach((i=>{const e=document.createElement("div");e.className="card shadow mb-4 w-75",e.innerHTML=`\n        <div class="card-header py-3 d-flex justify-content-center align-items-center">\n            <h6 class="m-0 font-weight-bold text-primary w-100" style="text-align: center;">${i.title}</h6>\n            <a href="${i.link}" class="">\n                <div class="col-auto btn btn-info">\n                    <i class="fas fa-arrow-right"></i>\n                </div>\n            </a>\n        </div>\n        <div class="card-body" style="text-align: center;">\n            ${i.description}\n        </div>\n    `,t.appendChild(e)}))})();
